import styled from '@emotion/styled';

import { chatMessageBodyTypography } from '../../shared/typography';
import { MARKDOWN_CHAT_MESSAGE_CLASS } from './constants';

export const MarkdownWrapper = styled.div`
  font-family: var(--ai-chat-font-family-body, 'Work Sans');
  font-size: var(--ai-chat-font-size-lg, 16px);
  font-weight: var(--ai-chat-font-weight-regular, 400);
  line-height: var(--ai-chat-line-height-normal, 1.5);
  color: var(--ai-chat-color-text-primary, #141414);

  &.${MARKDOWN_CHAT_MESSAGE_CLASS} {
    ${chatMessageBodyTypography}
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    margin-top: var(--ai-chat-space-4, 16px);
    margin-bottom: var(--ai-chat-space-2, 8px);
    font-weight: var(--ai-chat-font-weight-semibold, 600);
    line-height: var(--ai-chat-line-height-snug, 1.4);
  }

  h1 {
    font-size: var(--ai-chat-font-size-2xl, 20px);
  }
  h2 {
    font-size: var(--ai-chat-font-size-xl, 18px);
  }
  h3 {
    font-size: var(--ai-chat-font-size-lg, 16px);
  }

  p {
    margin: 0;
  }

  > *:first-of-type {
    margin-top: 0;
  }
  > *:last-of-type {
    margin-bottom: 0;
  }

  ul,
  ol {
    margin: var(--ai-chat-space-2, 8px) 0;
    padding-left: var(--ai-chat-space-6, 24px);
  }

  li {
    margin: var(--ai-chat-space-1, 4px) 0;
  }

  strong {
    font-weight: var(--ai-chat-font-weight-semibold, 600);
  }

  code {
    background-color: var(--ai-chat-color-bg-secondary, #f3f3f3);
    padding: 2px var(--ai-chat-space-1, 4px);
    border-radius: var(--ai-chat-radius-sm, 4px);
    font-family: monospace;
    font-size: 13px;
  }

  pre {
    background-color: var(--ai-chat-color-bg-secondary, #f3f3f3);
    padding: var(--ai-chat-space-3, 12px);
    border-radius: var(--ai-chat-radius-md, 8px);
    overflow-x: auto;
    margin: var(--ai-chat-space-2, 8px) 0;
  }

  pre code {
    background: none;
    padding: 0;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    margin: var(--ai-chat-space-3, 12px) 0;
    font-size: var(--ai-chat-font-size-lg, 16px);
  }

  th,
  td {
    padding: var(--ai-chat-space-2, 8px) var(--ai-chat-space-3, 12px);
    text-align: left;
    border: var(--ai-chat-border-width-thin, 1px) solid
      var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
  }

  th {
    background-color: var(--ai-chat-color-bg-default, #ffffff);
    font-weight: var(--ai-chat-font-weight-semibold, 600);
    border-bottom: var(--ai-chat-border-width-medium, 2px) solid
      var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
  }

  tr:nth-of-type(even) {
    background-color: var(--ai-chat-color-bg-default-subtle, #fafafa);
  }

  blockquote {
    border-left: 3px solid var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
    margin: var(--ai-chat-space-2, 8px) 0;
    padding-left: var(--ai-chat-space-4, 16px);
    color: var(--ai-chat-color-fg-secondary, #5c5c5c);
  }

  a {
    color: var(--ai-chat-color-link, #1890ff);
    text-decoration: none;
  }

  a:hover {
    text-decoration: underline;
  }

  hr {
    border: none;
    border-top: var(--ai-chat-border-width-thin, 1px) solid
      var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
    margin: var(--ai-chat-space-4, 16px) 0;
  }

  &.ai-summary-volume-pages {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-auto-rows: auto;
    column-gap: var(--ai-chat-space-4, 16px);
    row-gap: var(--ai-chat-space-2, 8px);

    > div#markdown-table-scroll-container {
      border-radius: var(--ai-chat-radius-lg, 12px);
      border: var(--ai-chat-border-width-thin, 1px) solid
        var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
      > table {
        padding: var(--ai-chat-space-4, 16px);
      }
    }
    > ul {
      grid-column: 1 / -1;
      grid-row: 1;
      margin: 0;
      padding-left: var(--ai-chat-space-5, 20px);
      font-size: var(--ai-chat-font-size-md, 14px);
      color: var(--ai-chat-color-fg-secondary, #5c5c5c);

      li {
        margin: var(--ai-chat-space-1, 4px) 0;

        strong {
          color: var(--ai-chat-color-text-primary, #141414);
        }
      }
    }

    > div:nth-of-type(1) {
      grid-area: 2 / 1 / 4 / 3;
      background-image: linear-gradient(
        90deg,
        rgba(255, 222, 112, 0.48) 0%,
        rgba(255, 255, 255, 0.48) 100%
      );
      background-clip: padding-box;
      border: transparent;
    }
    > div:nth-of-type(2) {
      grid-area: 4 / 1 / 6 / 3;
      background-image: linear-gradient(
        90deg,
        rgba(112, 198, 255, 0.48) 0%,
        rgba(255, 255, 255, 0.48) 100%
      );
      background-clip: padding-box;
      border: transparent;
    }
    > div:nth-of-type(3) {
      grid-area: 2 / 3 / 3 / 5;
      background: var(--ai-chat-color-bg-default, #ffffff);
    }
    > div:nth-of-type(4) {
      grid-area: 3 / 3 / 4 / 5;
      background: var(--ai-chat-color-bg-default, #ffffff);
    }
    > div:nth-of-type(5) {
      grid-area: 4 / 3 / 5 / 5;
      background: var(--ai-chat-color-bg-default, #ffffff);
    }
    > div:nth-of-type(6) {
      grid-area: 5 / 3 / 6 / 5;
      background: var(--ai-chat-color-bg-default, #ffffff);
    }

    tr:nth-of-type(even) {
      background-color: transparent;
      > td {
        border-bottom: var(--ai-chat-border-width-thin, 1px) solid
          var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
        border-top: var(--ai-chat-border-width-thin, 1px) solid
          var(--ai-chat-color-bd-tertiary, rgba(0, 0, 0, 0.08));
      }
    }

    > div {
      margin: 0;
      min-width: 0;
      overflow: hidden;
    }

    table {
      height: 100%;
      width: 100%;
      min-width: 0;
      border-collapse: separate !important;
      border-spacing: 0 !important;
      margin: 0;
      table-layout: fixed;
    }

    th {
      text-align: left;
      background: transparent;
      border: none;
      padding: 0;
    }

    td {
      vertical-align: top;
      background: transparent;
      border: none;
      font-size: var(--ai-chat-font-size-md, 14px);
      color: var(--ai-chat-color-text-primary, #141414);

      strong {
        color: var(--ai-chat-color-text-primary, #141414);
        display: block;
      }

      img {
        width: var(--ai-chat-sizing-lg, 32px);
        height: var(--ai-chat-sizing-lg, 32px);
        border-radius: 50%;
        object-fit: cover;
        vertical-align: middle;
        margin-right: var(--ai-chat-space-2, 8px);
        margin-bottom: var(--ai-chat-space-2, 8px);
      }
    }

    > div:nth-of-type(n + 3) th {
      font-size: var(--ai-chat-font-size-md, 14px);
      font-weight: var(--ai-chat-font-weight-regular, 400);
      color: var(--ai-chat-color-fg-secondary, #5c5c5c);
      padding: var(--ai-chat-space-4, 16px);
      vertical-align: top;
    }

    > div:nth-of-type(n + 3) th:first-of-type {
      width: 112px;
      border: none;
      padding: var(--ai-chat-space-4, 16px) var(--ai-chat-space-2, 8px)
        var(--ai-chat-space-4, 16px) var(--ai-chat-space-4, 16px);

      img {
        width: 100%;
        height: 90px;
        display: block;
        object-fit: cover;
        object-position: top;
        margin: 0;
      }
    }

    > div:nth-of-type(n + 3) th:last-of-type {
      border: none;
      padding: var(--ai-chat-space-4, 16px) var(--ai-chat-space-4, 16px)
        var(--ai-chat-space-4, 16px) var(--ai-chat-space-3, 12px);

      strong {
        display: block;
        color: var(--ai-chat-color-text-primary, #141414);
        font-weight: var(--ai-chat-font-weight-semibold, 600);
        margin-bottom: var(--ai-chat-space-1, 4px);
      }
    }
  }
`;

interface TableScrollContainerProps {
  $enableHorizontalScroll?: boolean;
}

export const TableScrollContainer = styled.div<TableScrollContainerProps>`
  width: 100%;
  max-width: 100%;
  overflow-x: ${({ $enableHorizontalScroll = true }) =>
    $enableHorizontalScroll ? 'auto' : 'visible'};
  margin: var(--ai-chat-space-3, 12px) 0;

  table {
    min-width: max-content;
    margin: 0;
  }
`;
